# Coordinator collection of the single Stage2 return from each site.
 if(length(a)<3L)stop('Supply all one-pass Stage2 return directories.')
 returns<-a[-c(1,2)];bundle<-config$stage2_bundle%||%file.path(root,'stage2_parameters')
 bm<-deploy_validate_inventory(bundle,'bundle_manifest.json');sites<-unlist(bm$sites)
 step<-function(key,script,args=character())deploy_step(root,key,script,args)
 state<-list(bundle_md5=unname(tools::md5sum(file.path(bundle,'bundle_manifest.json'))),return_manifest_md5=setNames(as.list(vapply(returns,function(p)unname(tools::md5sum(file.path(p,'return_manifest.json'))),character(1))),normalizePath(returns)))
 statefile<-file.path(root,'local/collection_inputs.json')
 if(file.exists(statefile)){if(!identical(deploy_read(statefile),state))stop('Collection inputs changed. Choose a fresh coordinator output root.')}else deploy_json(state,statefile)
 step('collect_one_pass','diagnostics/stage2/central_collect.R',c(bundle,file.path(root,'reports'),returns))
 step('survival_reconstruct','diagnostics/stage2/central_survival.R',c(file.path(root,'survival_reconstruction'),file.path(returns,'survival')))
 step('pooled_AJ_KM','diagnostics/pooled_survival/central_pool.R',c(file.path(root,'reports/pooled_survival'),file.path(root,'survival_reconstruction/grid'),file.path(root,'survival_reconstruction/sites',sites)))
 python<-config$python%||%file.path(clif_root,'.venv',if(.Platform$OS.type=='windows')'Scripts/python.exe' else 'bin/python')
 if(!file.exists(python))stop('Set coordinator python to the plotting virtual environment.')
 deploy_step(root,'pool_prediction','diagnostics/stage2/central_prediction.py',c(file.path(root,'reports/pooled_prediction'),file.path(returns,'prediction')),python)
 deploy_step(root,'plot_competing','diagnostics/pooled_survival/plot_competing.py',file.path(root,'reports/pooled_survival'),python)
 cat('One-pass Stage2 returns collected; no further site exchange required. Reports: ',file.path(root,'reports'),'\n');quit(status=0)
